pug:
div.gmail-blend-screen.b-iq-utility-20
    div.gmail-blend-diff
        p.date {{ text_1 }}
        p.white-title.pb16.pt16 {{ text_2 }}
        p.white-text  {{ text_3 }}

styl:
u + .body .gmail-blend-screen.b-iq-utility-20 {  background: #000;
  mix-blend-mode: screen;  }
.b-iq-utility-20 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.b-iq-utility-20 .date {  border-radius: 10px;
  color: #ff8516;
  display: inline-block;
  font-family: Helvetica !important;
  font-size: 24px;
  font-style: normal;
  font-weight: 700;
  line-height: 36px;
  padding: 4px 12px;
  background: url("https://fsms.quadcode.com/storage/public/d8/0t/39261bdc700vi72g/bg-orange.png") center no-repeat;
  background-size: cover;  }
.b-iq-utility-20 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 48px;
  line-height: 58px;
  color: #f9f9f9;
  word-break: break-word;  }
@media screen and (max-width: 600px) {
  .b-iq-utility-20 .white-title {  font-size: 26px !important;
    line-height: 32px !important;
    padding-right: 0 !important;  }
}
.b-iq-utility-20 .white-text {  font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
